TypeScript example: configuring balanced retry preset:

import { RedwoodClient } from '@redwood/inference'
const client = new RedwoodClient({ retryPreset: 'balanced', retryTokenCap: 15000 })
const stream = client.chat.stream({ prompt: 'Explain async streams in 3 bullets' })
stream.on('data', (chunk) => console.log(chunk.text))
stream.on('retry_budget_exhausted', (meta) => console.warn('retry budget exhausted', meta))

Go example: opt-out behavior for mid-stream failures:

client := redwood.NewClient(redwood.Config{RetryPreset: redwood.PresetBalanced})
// Disable automatic mid-stream retries to let caller implement resume
client.Config.StreamAutoMidRetry = false
resp, err := client.Generate(ctx, request)
if err != nil { // handle and optionally call Resume with stored id-key }

Backoff pseudocode (decorrelated):

function decorrelatedBackoff(attempt, base, cap) {
  sleep = min(cap, random(base, sleep * factor))
  await wait(sleep)
}

Telemetry schema (events):
  - retry.attempted {sdk, preset, attempt_number, reason}
  - retry.exhausted {sdk, preset, budget, tokens_used}
  - idkey.generated {sdk, idkey_type}
